def path_exists(graph, s, t):
    seen = {s}
    stack = [s]
    while stack:
        n = stack.pop()
        if n == t: return True
        for nb in graph.get(n, []):
            if nb not in seen:
                seen.add(nb); stack.append(nb)
    return False
